// Verus program: Cartesian mesh grid for two non-empty Vec<f32> inputs.
//
// We build two matrices Xg, Yg of shape (y.len() rows) x (x.len() cols):
// - Xg[i][j] == x[j]
// - Yg[i][j] == y[i]

use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        result.0.len() == y.len(),
        result.1.len() == y.len(),
        forall|i: int| 0 <= i < y.len() ==> (
            result.0[i].len() == x.len()
            && result.1[i].len() == x.len()
        ),
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==> result.0[i][j] == x[j],
        forall|i: int, j: int|
            0 <= i < y.len() && 0 <= j < x.len() ==> result.1[i][j] == y[i],
{
    let mut xgrid: Vec<Vec<f32>> = Vec::new();
    let mut ygrid: Vec<Vec<f32>> = Vec::new();

    let mut i: usize = 0;
    while i < y.len()
        invariant
            0 <= i <= y.len(),
            xgrid.len() == i,
            ygrid.len() == i,
            forall|r: int| 0 <= r < i ==> (
                xgrid[r].len() == x.len()
                && ygrid[r].len() == x.len()
            ),
            forall|r: int, c: int|
                0 <= r < i && 0 <= c < x.len() ==> xgrid[r][c] == x[c],
            forall|r: int, c: int|
                0 <= r < i && 0 <= c < x.len() ==> ygrid[r][c] == y[r],
        decreases
            y.len() - i,
    {
        let mut row_x: Vec<f32> = Vec::new();
        let mut row_y: Vec<f32> = Vec::new();

        let mut j: usize = 0;
        while j < x.len()
            invariant
                0 <= j <= x.len(),
                row_x.len() == j,
                row_y.len() == j,
                forall|c: int| 0 <= c < j ==> row_x[c] == x[c],
                forall|c: int| 0 <= c < j ==> row_y[c] == y[i as int],
            decreases
                x.len() - j,
        {
            row_x.push(x[j]);
            row_y.push(y[i]);
            j += 1;
        }

        xgrid.push(row_x);
        ygrid.push(row_y);
        i += 1;
    }

    (xgrid, ygrid)
}

} // verus!